    // minInputLen walks the regexp to find the minimum length of any matchable input.
    int minInputLen(syntax::Regexp* re)
    {
        //Go switch emulation
        {
            auto condition = re->Op;
            int conditionId = -1;
            if(condition == syntax::OpAnyChar) { conditionId = 0; }
            else if(condition == syntax::OpAnyCharNotNL) { conditionId = 1; }
            else if(condition == syntax::OpCharClass) { conditionId = 2; }
            else if(condition == syntax::OpLiteral) { conditionId = 3; }
            else if(condition == syntax::OpCapture) { conditionId = 4; }
            else if(condition == syntax::OpPlus) { conditionId = 5; }
            else if(condition == syntax::OpRepeat) { conditionId = 6; }
            else if(condition == syntax::OpConcat) { conditionId = 7; }
            else if(condition == syntax::OpAlternate) { conditionId = 8; }
            switch(conditionId)
            {
                default:
                    return 0;
                    break;
                case 0:
                case 1:
                case 2:
                    return 1;
                    break;
                case 3:
                {
                    auto l = 0;
                    for(auto [gocpp_ignored, r] : re->Rune)
                    {
                        if(r == utf8::RuneError)
                        {
                            l++;
                        }
                        else
                        {
                            l += utf8::RuneLen(r);
                        }
                    }
                    return l;
                    break;
                }
                case 4:
                case 5:
                    return minInputLen(re->Sub[0]);
                    break;
                case 6:
                    return re->Min * minInputLen(re->Sub[0]);
                    break;
                case 7:
                {
                    auto l = 0;
                    for(auto [gocpp_ignored, sub] : re->Sub)
                    {
                        l += minInputLen(sub);
                    }
                    return l;
                    break;
                }
                case 8:
                {
                    auto l = minInputLen(re->Sub[0]);
                    int lnext = {};
                    for(auto [gocpp_ignored, sub] : re->Sub.make_slice(1))
                    {
                        lnext = minInputLen(sub);
                        if(lnext < l)
                        {
                            l = lnext;
                        }
                    }
                    return l;
                    break;
                }
            }
        }
    }

